from pathlib import Path
import json,hashlib,ast,difflib
T=Path(__file__).resolve().parents[1];root=T/'input';p=root/'ld01/provenance';p.mkdir(parents=True,exist_ok=False)
def ident(b):return {'bytes':len(b),'sha256':hashlib.sha256(b).hexdigest()}
def enc(v):return (json.dumps(v,sort_keys=True,indent=2)+'\n').encode()
old=(T/'retained/original/code/correspondence.py').read_bytes();new=(root/'code/correspondence.py').read_bytes();a=ast.parse(old);b=ast.parse(new);fa=next(n for n in a.body if isinstance(n,ast.FunctionDef) and n.name=='_public_predecessor');fb=next(n for n in b.body if isinstance(n,ast.FunctionDef) and n.name=='_public_predecessor')
assert [ast.dump(n) for n in a.body if n is not fa]==[ast.dump(n) for n in b.body if n is not fb]
assert old.splitlines(True)[:fa.lineno-1]==new.splitlines(True)[:fb.lineno-1] and old.splitlines(True)[fa.end_lineno:]==new.splitlines(True)[fb.end_lineno:]
changes={'only_existing_implementation_change':'code/correspondence.py:_public_predecessor','before':ident(old),'after':ident(new),'other_function_AST_and_outside_bytes':'UNCHANGED','runtime_sources':'UNCHANGED','producer':'UNCHANGED','predecessor_public_validator':'UNCHANGED','historical_results':'UNCHANGED'}
(p/'changed-files.json').write_bytes(enc(changes));(p/'implementation.diff').write_text(''.join(difflib.unified_diff(old.decode().splitlines(True),new.decode().splitlines(True),fromfile='original/code/correspondence.py',tofile='corrected/code/correspondence.py')))
(p/'intake.json').write_bytes((T/'preparation/intake.json').read_bytes())
saved=(root/'results/primary/launcher-details.json').read_bytes();v=json.loads(saved);before=ident(saved);oldpin=v['extension_components']['correspondence.py'];assert oldpin==ident(old);v['extension_components']['correspondence.py']=ident(new);corrected=(json.dumps(v,sort_keys=True,separators=(',',':'),allow_nan=False)+'\n').encode();q=root/'ld01/receipts';q.mkdir();(q/'corrected-launcher-details.json').write_bytes(corrected)
(p/'receipt-component-update.json').write_bytes(enc({'old_receipt':before,'corrected_receipt':ident(corrected),'sole_changed_path':'/extension_components/correspondence.py','before':oldpin,'after':ident(new),'preparation_not_validation':True,'actual_public_validation_required':True,'contexts_and_model_correspondence_unchanged':True,'no_submitted_receipt_repair':True}))
(p/'review-incorporation.json').write_bytes(enc({'review':'Formal-Lab6-I164-launcher-initial-details-independent-review.zip','identity':json.loads((p/'intake.json').read_bytes())['review'],'verdict':'NOT ACCEPTED AS COMPLETE — LD-01','remaining_source_correspondence':'Bounded scoped support; not overall completion','completed_independent_checks':523,'qualified_rows':80,'unfinished_audit_completed_separately':'zero replay','defect_observations':2,'Engineering_prior_groups':{'source':66,'primary':862,'recovered':391},'Engineering_prior_zero_control_failures':3,'older_accounting':'Retained unchanged, not repaired or combined','public_negative_layers':'Prior pre-derivation gates, authenticated-basis cores and receipt-comparison cores remain distinct; no full public negative derivation claimed','correction_independent_closure':'PENDING'}))
(p/'monitoring-api-reference.txt').write_text('Reference: https://docs.python.org/3.12/library/sys.monitoring.html (retrieved 2026-10-31; page served as 3.12.16). The documented API distinguishes reservation, event masks, callback registration and release; release does not clear callbacks or event masks. These facts inform the separate cleanup attempts. Name-object identity is not claimed as a generic Python API guarantee: focused controls inspect the actual retained CPython3.12.14 profile. Attempts to retrieve v3.12.14 instrumentation.c through web retrieval were unavailable; no compiled-source or installed-wheel authentication is claimed. This is validator-local resource management, not an application operating-envelope or policy revision.\n')
manifest={f.relative_to(root).as_posix():ident(f.read_bytes()) for f in sorted(root.rglob('*')) if f.is_file() and f!=root/'MANIFEST.json'};(root/'MANIFEST.json').write_bytes(enc(manifest));(T/'preparation/frozen-manifest.json').write_bytes((root/'MANIFEST.json').read_bytes());print(json.dumps({'files':len(manifest)+1,'changed':changes,'receipt':ident(corrected)}),flush=True)
